public class Account {
    private long cents;                    // hidden; invariant: cents >= 0

    public void deposit(long amount) {
        if (amount <= 0) throw new IllegalArgumentException("amount must be positive");
        cents += amount;
    }

    public void withdraw(long amount) {
        if (amount <= 0 || amount > cents) throw new IllegalArgumentException("invalid amount");
        cents -= amount;
    }

    public long balance() { return cents; }
}

from abc import ABC, abstractmethod

class Storage(ABC):
    @abstractmethod
    def save(self, key, data): ...
    @abstractmethod
    def load(self, key): ...

class MemoryStorage(Storage):
    def __init__(self):
        self._d = {}
    def save(self, key, data):
        self._d[key] = data
    def load(self, key):
        return self._d[key]

def backup(store: Storage, key, data):    # knows only the interface
    store.save(key, data)

store = MemoryStorage()
backup(store, "note", "hello")
print(store.load("note"))                 # hello

