from abc import ABC, abstractmethod

class Discount(ABC):
    @abstractmethod
    def apply(self, price): ...

class NoDiscount(Discount):
    def apply(self, price):
        return price

class PercentOff(Discount):
    def __init__(self, pct):
        self.pct = pct
    def apply(self, price):
        return price * (1 - self.pct / 100)

def checkout(price, discount: Discount):   # closed for change, open for new Discounts
    return discount.apply(price)

print(checkout(200, PercentOff(25)))       # 150.0

class EventBus:
    def __init__(self):
        self._subs = {}

    def subscribe(self, topic, fn):
        self._subs.setdefault(topic, []).append(fn)

    def publish(self, topic, payload):
        for fn in self._subs.get(topic, []):
            fn(payload)

bus = EventBus()
bus.subscribe("order", lambda o: print("email", o))
bus.subscribe("order", lambda o: print("stock", o))
bus.publish("order", 7)      # email 7, then stock 7
